pub type LPARAM = isize;
pub type LRESULT = isize;
pub type UINT = u32;
pub type UINT_PTR = usize;
pub type DWORD = u32;
pub type BOOL = i32;
pub type LONG = i32;
pub type ULONG = u32;
pub type WORD = u16;
pub type BYTE = u8;
pub type WCHAR = u16;
/// The `GWLP_*` and `SWP_*` argument slots are pointer-sized on x64 and 32-bit on x86; `isize`
/// matches both, which is why every declaration below uses it rather than `LONG`.
pub type LONG_PTR = isize;
pub type DWORD_PTR = usize;
pub type FN_WNDPROC = unsafe extern "system" fn(HWND, UINT, WPARAM, LPARAM) -> LRESULT;

