// ---------------------------------------------------------------------------------------------
// helpers
// ---------------------------------------------------------------------------------------------

/// UTF-16 with a trailing NUL, for the handful of `*const WCHAR` arguments. A fixed buffer rather
/// than an allocation: the only strings handed to the API here are a class name, a title and a
/// tooltip, all bounded and all created once.
#[must_use]
pub fn wide(s: &str) -> Vec<WCHAR> {
    let mut v: Vec<WCHAR> = s.encode_utf16().collect();
    v.push(0);
    v
}

/// `ERROR_ALREADY_EXISTS`, the only `GetLastError` value the startup path reads.
pub const ERROR_ALREADY_EXISTS: DWORD = 183;
pub const ERROR_PROC_NOT_FOUND: DWORD = 127;

#[must_use]
pub fn last_error() -> DWORD {
    unsafe { GetLastError() }
}

/// Last-resort DPI: `GetDpiForWindow` is Win10 1607+, so it is resolved at runtime and the fallback
/// is the old system-wide value read off a screen DC.
#[must_use]
pub fn dpi_of_window(hwnd: HWND) -> UINT {
    unsafe {
        // The symbol is imported normally here, and Windows 10 1607 is the documented floor for the
        // whole app (see README), so no dynamic resolution is needed. If the floor ever moves back
        // to Windows 8, this is the one call that must become a GetProcAddress lookup.
        let d = GetDpiForWindow(hwnd);
        if d != 0 {
            return d;
        }
        let dc = GetDC(std::ptr::null_mut());
        let x = GetDeviceCaps(dc, LOGPIXELSX);
        let y = GetDeviceCaps(dc, LOGPIXELSY);
        ReleaseDC(std::ptr::null_mut(), dc);
        if x > 0 && x == y {
            x as UINT
        } else {
            96
        }
    }
}

/// Ask the process to be Per-Monitor V2 aware. On builds without the export the call is skipped and
/// the app still works, just without per-monitor rescaling — which is why this is looked up by name
/// instead of imported.
///
/// # Safety
///
/// Calls a Win32 entry point; the pointer returned by `GetProcAddress` is cast to the function's
/// type, which is only sound if the name resolves to that API. It does.
pub unsafe fn apply_dpi_awareness() -> bool {
    let module = GetModuleHandleW(wide("user32.dll").as_ptr());
    if module.is_null() {
        return false;
    }
    let name = b"SetProcessDpiAwarenessContext\0";
    let addr = GetProcAddress(module, name.as_ptr() as *const i8);
    if addr.is_null() {
        // Pre-1703: the best available is system-DPI aware, which is still better than nothing.
        SetProcessDPIAware();
        return false;
    }
    type Fn = unsafe extern "system" fn(HANDLE) -> BOOL;
    let f: Fn = std::mem::transmute::<*const c_void, Fn>(addr);
    f(DPI_AWARENESS_CONTEXT_PM_V2) != 0
}

/// `SHAppBarMessage` is in `shell32` but the answers are advisory (which edge the taskbar is on),
/// so a failure is simply "no taskbar information", not an error.
#[must_use]
pub fn query_taskbar(hwnd: HWND) -> Option<(bool, bool)> {
    unsafe {
        let module = GetModuleHandleW(wide("shell32.dll").as_ptr());
        if module.is_null() {
            return None;
        }
        let name = b"SHAppBarMessage\0";
        let addr = GetProcAddress(module, name.as_ptr() as *const i8);
        if addr.is_null() {
            return None;
        }
        type Fn = unsafe extern "system" fn(DWORD, *mut APPBARDATA) -> ULONG;
        let f: Fn = std::mem::transmute::<*const c_void, Fn>(addr);
        let mut state = APPBARDATA { cb_size: size_of::<APPBARDATA>() as UINT, hwnd, ..Default::default() };
        let state_ok = f(ABM_GETSTATE, &mut state) != 0;
        let auto_hide = state_ok && (state.l_param as DWORD & ABS_AUTOHIDE) != 0;
        let mut pos = APPBARDATA { cb_size: size_of::<APPBARDATA>() as UINT, hwnd, ..Default::default() };
        if f(ABM_GETTASKBARPOS, &mut pos) == 0 {
            return Some((false, auto_hide));
        }
        Some((pos.edge == ABE_TOP, auto_hide))
    }
}
